INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 21, 'theory', 'Quiz: non-relational databases');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 0, 'Why can''t you query "all users from Kazan" in a key-value store?', '["Because a city is not a string", "Because queries are forbidden by the license", "The value is a black box to the database: there are no queries by content, only access by key", "Because keys must be numbers"]', 2, 'The solution is to build the needed key in advance, or a second pointer record, and maintain it in the application; or to choose a document database with indexes on fields.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 1, 'When is it better in a document database to reference by identifier rather than embed the data?', '["When the data is shared by many documents and changes often — otherwise you would have to update it everywhere", "When the data is always read together and almost never changes", "Never: references are forbidden", "When the document is too short"]', 0, 'Embedding gives fast reads but duplicates a fact. Shared and frequently changing data (a product name, a price) is kept in one place and fetched with a second query.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 2, 'What does "modeling from queries" mean in Cassandra?', '["Tables are created first, queries are invented later", "For each query type you create its own table with a suitable key, duplicating data", "All data is stored in one table without a key", "Queries are executed in the application"]', 1, 'There are no joins, so the same fact is stored in several tables under different keys; you watch the partition size and hot keys.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 3, 'How does a graph beat a chain of JOINs in the task of "friends of friends of friends"?', '["A graph stores nodes without relationships", "A graph has no indexes", "A graph is always faster for aggregates", "A node stores direct links to its neighbors, and following an edge is almost free, while every JOIN makes the query more expensive"]', 3, 'Graph databases are optimized for traversing relationships; the cost is the difficulty of horizontal scaling and of aggregates over the whole collection.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 4, 'What does the inverted index of a search engine store?', '["For each document, a list of its words in the original order", "For each word, a list of the documents where it appears", "Only document titles", "Document hashes"]', 1, 'The query is split into words, a list of documents is taken for each, the lists are intersected or merged and ranked by relevance.');
